"""Build crawlable static HTML and explicitly selected public assets."""
from pathlib import Path
import json, html, shutil, re, hashlib
from assets import build_assets, ROOT, DEST

OUT=ROOT/'dist'; OUT.mkdir(exist_ok=True)
cfg=json.loads((ROOT/'config/site.json').read_text())
photos=build_assets(); byid={p['id']:p for p in photos}
e=lambda x:html.escape(str(x),quote=True)
DOMAIN='https://sdatarneit.au'
NDIS='https://ndis.gov.au/participants/home-and-living/types-home-and-living-supports/what-specialist-disability-accommodation-sda'
SIL='https://ndis.gov.au/participants/home-and-living/types-home-and-living-supports/what-supported-independent-living-sil'

def img(slug,alt,cls='',eager=False,plan=False):
    widths=[400,1000,2000] if plan else [240,800,1600]
    return f'<img class="{cls}" src="/assets/{slug}-{widths[1]}.webp" srcset="'+', '.join(f'/assets/{slug}-{w}.webp {w}w' for w in widths)+f'" sizes="(max-width: 700px) 100vw, 70vw" alt="{e(alt)}" width="{2583 if plan else 1600}" height="{2600 if plan else 900}" '+('fetchpriority="high" loading="eager"' if eager else 'loading="lazy"')+' decoding="async">'
def photo(n,cls='',eager=False):return img(byid[n]['slug'],byid[n]['caption'],cls,eager)
def link(url,txt,cls='text-link'):return f'<a class="{cls}" href="{url}">{txt}<span aria-hidden="true"> ↗</span></a>'
def section_title(kicker,title,desc=''):return f'<div class="section-heading"><p class="eyebrow">{kicker}</p><h2>{title}</h2>'+ (f'<p>{desc}</p>' if desc else '')+'</div>'
def faq(q,a):return f'<details class="faq"><summary>{q}</summary><div>{a}</div></details>'
def cta():return '<section class="cta-band"><div><p class="eyebrow">YOUR NEXT STEP</p><h2>Let’s talk about the home.</h2><p>Ask the owner your questions. Inspections and suitability checks are coordinated through Disability Forever Homes, the property manager.</p></div>'+link('/enquiries/','Ask about the home','button light')+'</section>'

nav='<a href="/">Overview</a><a href="/the-home/">The home</a><a href="/living-in-tarneit/">Life in Tarneit</a><a href="/sda-and-support/">SDA &amp; support</a>'
def page(path,title,description,body):
    canonical=DOMAIN+path
    currentnav=nav.replace(f'href="{path}"',f'href="{path}" aria-current="page"')
    schema={'@context':'https://schema.org','@type':'WebSite','name':'SDA Tarneit','url':DOMAIN} if path=='/' else {'@context':'https://schema.org','@type':'WebPage','name':title,'url':canonical}
    doc=f'''<!doctype html><html lang="en-AU"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{e(title)}</title><meta name="description" content="{e(description)}"><link rel="canonical" href="{canonical}"><meta name="theme-color" content="#173c33"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(description)}"><meta property="og:url" content="{canonical}"><meta property="og:type" content="website"><link rel="icon" type="image/svg+xml" href="/favicon.svg"><link rel="stylesheet" href="/styles.css"><script defer src="/app.js"></script><script type="application/ld+json">{json.dumps(schema)}</script></head><body><a class="skip-link" href="#main">Skip to content</a><header class="site-header"><div class="header-inner"><a href="/" class="brand" aria-label="SDA Tarneit home"><svg viewBox="0 0 40 40" aria-hidden="true"><path d="M5 20 20 7l15 13M10 17v18h20V17M17 35V23h7v12"/></svg><span>SDA<span class="brand-place">TARNEIT</span></span></a><button class="menu-toggle" aria-label="Open navigation" aria-expanded="false" aria-controls="navigation">Menu <span aria-hidden="true">☰</span></button><nav id="navigation" aria-label="Main navigation">{currentnav}</nav><a class="button header-enquire" href="/enquiries/">Enquire <span aria-hidden="true">↗</span></a></div></header><main id="main">{body}</main><footer><div class="footer-top"><a class="footer-brand" href="/">SDA TARNEIT<span>One home. A considered next step.</span></a><div><p>Social Street, Tarneit VIC 3029<br>Wyndham · Melbourne’s western suburbs</p></div><div><a href="/enquiries/">Enquiries &amp; inspections</a><a href="/privacy/">Privacy</a><a href="/sda-and-support/">Frequently asked questions</a></div></div><div class="footer-bottom"><p>This website showcases one home in Tarneit. Availability, funding and suitability require individual confirmation.</p><span>© 2026 SDA Tarneit</span></div></footer><dialog id="media-dialog" aria-labelledby="media-title"><div class="dialog-top"><div><h2 id="media-title">Property photos</h2><p id="media-note"></p></div><button id="close-dialog" class="icon-button" aria-label="Close media viewer">✕</button></div><div id="media-content"></div><div id="dialog-navigation"><button class="icon-button" id="dialog-prev" aria-label="Previous photo">←</button><p id="dialog-counter" aria-live="polite"></p><button class="icon-button" id="dialog-next" aria-label="Next photo">→</button></div><div id="dialog-thumbnails" aria-label="Choose a photo"></div></dialog></body></html>'''
    for asset in ['styles.css','app.js']:
        version=hashlib.sha256((ROOT/'src'/asset).read_bytes()).hexdigest()[:12]
        doc=doc.replace(f'"/{asset}"',f'"/{asset}?v={version}"')
    folder=OUT/path.strip('/');folder.mkdir(parents=True,exist_ok=True);(folder/'index.html').write_text(doc,encoding='utf-8')

hero_index=photos.index(byid[51])
thumbs=''.join(f'<a href="/assets/{p["slug"]}-1600.webp" class="photo-thumb" data-photo="{i}" aria-label="Photo {i+1}: {e(p["caption"])}"><img src="/assets/{p["slug"]}-240.webp" alt="{e(p["caption"])}" width="240" height="135" loading="lazy"><span>{i+1:02}</span></a>' for i,p in enumerate(photos))
quick=''.join(f'<a href="/assets/{byid[n]["slug"]}-1600.webp" data-main-photo="{photos.index(byid[n])}" aria-label="Show {e(byid[n]["caption"])}"><img src="/assets/{byid[n]["slug"]}-240.webp" width="240" height="135" alt="{e(byid[n]["caption"])}" loading="lazy"></a>' for n in [51,8,29,80,97,108])
gallery=f'''<section class="property-media" aria-label="Explore the property"><div class="media-grid"><div class="main-photo"><a id="main-photo-link" href="/assets/photo-051-1600.webp" data-photo="{hero_index}" aria-label="Enlarge property photo">{photo(51,'hero-image',True)}</a><span class="photo-label">THE ACTUAL HOME</span><div class="main-photo-controls"><button id="main-prev" class="icon-button" aria-label="Previous property photo">←</button><span id="main-counter" aria-live="polite">{hero_index+1} / {len(photos)}</span><button id="main-next" class="icon-button" aria-label="Next property photo">→</button></div></div><div class="media-options"><a class="media-tile" href="#all-photos" data-photo="0">{photo(8)}<span><b>Browse photos</b><small>{len(photos)} selected images <i aria-hidden="true">↗</i></small></span></a><a class="media-tile" href="/walkthrough/" data-video>{photo(75)}<span><b><i aria-hidden="true">▷</i> Watch walkthrough</b><small>2 min 15 sec <i aria-hidden="true">↗</i></small></span></a><a class="floorplan-tile" href="/the-home/#floorplans"><svg viewBox="0 0 40 40" aria-hidden="true"><path d="M5 5h30v30H5zM5 17h14V5M19 17v18M19 26h16M27 5v12h8"/></svg><span><b>View floorplan</b><small>Understand the layout</small></span><i aria-hidden="true">↗</i></a></div></div><div class="quick-thumbs" aria-label="Property photo previews">{quick}<a class="all-photos-button" href="#all-photos">All {len(photos)} photos →</a></div><p class="media-disclaimer">Property photos are taken from the recorded walkthrough. On-image availability and distance captions are not current confirmations. Furniture shown is not necessarily included.</p><details id="all-photos" class="photo-collection"><summary>Explore all {len(photos)} photos</summary><div class="thumbnail-grid">{thumbs}</div></details></section>'''

home=f'''<div class="wrap"><section class="intro"><p class="eyebrow">SOCIAL STREET · TARNEIT · VIC 3029</p><div class="intro-line"><div><h1>SDA accommodation in Tarneit.<br><em>A place to feel at home.</em></h1><p class="intro-copy">A High Physical Support SDA home with two participant bedrooms. See the actual spaces and start a conversation about what matters to you.</p></div><a href="/enquiries/" class="text-link intro-cta">Ask about this home <span aria-hidden="true">↗</span></a></div></section>{gallery}<section class="facts" aria-label="Home at a glance"><div><strong>2</strong><span>Participant bedrooms</span></div><div><strong>+1</strong><span>Overnight assistance room</span></div><div><strong>3</strong><span>Shower bathrooms · no baths</span></div><div><strong>2</strong><span>Garage spaces</span></div></section><section class="split section-space"><div>{section_title('A CLOSER LOOK','Your own space.<br>A home to share.')}<p>This Social Street home brings two participant bedrooms together with a shared kitchen, dining and living area, a covered alfresco and a rear lawn. Each participant bedroom has an adjoining ensuite. There is also a separate bedroom for overnight onsite assistance (OOA).</p><p>One participant bedroom is shown furnished. The other is shown unfurnished, making it easier to see its layout. Any furniture or equipment inclusions should be discussed before making a decision.</p><p>Whether you are exploring SDA housing for yourself, a family member or someone you support, the photographs and 2D plan are a starting point for a more personal conversation.</p>{link('/the-home/','Explore the home & accessibility')}</div><figure class="editorial-image">{photo(29)}<figcaption>Participant bedroom one · shown furnished</figcaption></figure></section><section class="feature-links section-space">{section_title('MAKE AN INFORMED CHOICE','Get to know the home, at your pace.')}<div class="three-cards"><article><span class="card-number">01 / THE SPACES</span><h3>See the layout</h3><p>Compare the two participant bedrooms, the OOA room and the shared spaces. The 2D plan gives the more faithful view of the layout.</p>{link('/the-home/#floorplans','Explore the plans')}</article><article><span class="card-number">02 / YOUR REQUIREMENTS</span><h3>Ask the practical questions</h3><p>Bring your questions about movement through the home, bathroom setup, equipment and support arrangements. Suitability needs an individual check.</p>{link('/the-home/#accessibility','Accessibility & suitability')}</article><article><span class="card-number">03 / YOUR NEXT STEP</span><h3>Arrange a closer look</h3><p>Enquiries go to the owner. Disability Forever Homes, the property manager, coordinates inspections and suitability checks.</p>{link('/enquiries/','Enquiries & inspections')}</article></div></section><section class="split reverse section-space"><figure class="editorial-image">{photo(97)}<figcaption>Covered alfresco and the home’s rear garden</figcaption></figure><div>{section_title('LIVING IN TARNEIT','Room for everyday life.')}<p>A home is more than its room count. The outdoor deck, shared dining area and garden offer different spaces to spend time, alongside the privacy of the participant bedrooms.</p><p>Tarneit is in Wyndham, in Melbourne’s western suburbs. This website is about this one home—not a network of properties across western Melbourne.</p><p>Take a look at the supplied photos of the local playground and Tarneit Central shopping centre, and use them to start planning the amenities and routes that matter to you.</p>{link('/living-in-tarneit/','Explore the neighbourhood')}</div></section><section class="support-intro section-space">{section_title('SDA & SUPPORT','A clear starting point for your questions.')}<div class="two-columns"><div><p>Specialist disability accommodation (SDA) is the housing itself. Daily support arrangements are a separate discussion. An OOA room describes a space in the home; it does not by itself confirm staffing, overnight support or a particular SIL provider.</p><p>Participants, families, support coordinators and SIL providers are welcome to explore the home and ask questions about the next steps.</p>{link('/sda-and-support/','Understand SDA & support arrangements')}</div><div>{faq('Are there SDA vacancies at this Tarneit home?','<p>Ask the owner for the current position. Photos and the recorded walkthrough do not establish current availability, room allocation or a move-in date.</p>')}{faq('Looking for High Physical Support SDA in Tarneit?','<p>The owner confirms this home is enrolled for High Physical Support SDA. Enquiries involving other SDA categories are also welcome, subject to funding and individual suitability checks with the property manager. This site does not determine funding eligibility or guarantee suitability.</p>')}{faq('Can I inspect the home?','<p>Start with an enquiry to the owner. Inspections and suitability checks are coordinated through Disability Forever Homes.</p>')}</div></div></section>{cta()}</div>'''
page('/','SDA Tarneit | Explore the Social Street SDA home','Explore SDA accommodation on Social Street, Tarneit: two participant bedrooms, an OOA room, photos, walkthrough and plans. Ask about suitability and inspections.',home)

plans=f'''<section id="floorplans" class="section-space">{section_title('UNDERSTAND THE LAYOUT','Two different views. One actual home.','Use the 2D plan to understand the layout. Use the 3D concept only to imagine how furnished spaces might look.')}<div class="plan-grid"><article><a href="/assets/tarneit-floor-plan.svg" data-plan="2d">{img('plan-2d','2D floor plan showing two participant bedrooms, OOA room, three shower bathrooms and the site layout',plan=True)}</a><p class="eyebrow">LAYOUT REFERENCE</p><h3>2D floor plan</h3><p>The more faithful layout, redrawn from the supplied construction drawings and updated with the owner’s bathroom and outdoor-area corrections. It is an illustrative marketing plan, not a construction drawing.</p><div class="link-row">{link('/assets/tarneit-floor-plan.pdf','Download PDF')}{link('/assets/tarneit-floor-plan.svg','Open full-size plan')}</div></article><article><a href="/assets/plan-3d-2000.webp" data-plan="3d">{img('plan-3d','Illustrative furnished 3D concept of the home, not a photograph or authoritative floorplan',plan=True)}</a><p class="eyebrow">ILLUSTRATIVE FURNISHED CONCEPT</p><h3>3D concept view</h3><p>This is not a photograph or an authoritative floorplan. Furniture, fittings and bathroom representations may differ from the actual home. No rooms in the actual home have a bathtub.</p><p>Furniture pictured does not establish what is included.</p>{link('/assets/plan-3d-2000.webp','Open concept image')}</article></div></section>'''
features=f'''<div class="wrap"><section class="page-intro"><p class="eyebrow">THE SOCIAL STREET HOME</p><h1>Spaces to make your own.</h1><p>Two participant bedrooms, a separate overnight assistance room and shared spaces for everyday living.</p></section><div class="wide-image">{photo(72,'',True)}</div><section class="section-space two-columns"><div><h2>Bedrooms and bathrooms</h2><p>Both participant bedrooms are labelled 3.73 × 3.73 metres in the supplied drawings and each has an adjoining shower ensuite. The separate OOA bedroom is labelled 2.96 × 3.20 metres.</p><p>There are three shower bathrooms in total, including the OOA ensuite. There are no bathtubs. The construction drawing labels the OOA adjoining room “WC”; the owner has confirmed it contains a toilet, vanity and shower.</p><p>One participant bedroom is currently shown furnished. Confirm any furniture, appliance or equipment inclusions with the owner.</p></div><div><h2>Shared living and outdoors</h2><p>The kitchen, living and dining area is shown as one connected space. The photographs show kitchen cabinetry, dining space, split-system units and access to a covered alfresco.</p><p>The outdoor layout includes rear and front lawn, garden beds, a concrete side path and an angled driveway. The marketing plan shows these outdoor areas approximately.</p><p>A double garage and laundry space are also shown. Ask how these spaces can be used alongside individual equipment and access requirements.</p></div></section><section id="accessibility" class="tinted section-space">{section_title('ACCESSIBILITY & SUITABILITY','Look closely. Ask specifically.')}<p>The photos show shower areas with support rails, a kitchen benchtop with space underneath, and outdoor access. The drawings also contain accessibility dimensions and provisions. A photograph or drawing is not a substitute for checking the completed home against your needs.</p><div class="two-columns"><div><h3>Useful questions for an inspection</h3><ul class="check-list"><li>Do the doorways, turning spaces and routes work with your mobility equipment?</li><li>Does the shower, toilet and transfer layout meet your requirements?</li><li>How do the entrance, driveway and alfresco transitions work for you?</li></ul></div><div><h3>Equipment and support</h3><ul class="check-list"><li>Which equipment is installed and which items are only provisions in the drawings?</li><li>What are the confirmed power, hoist and assistive-technology arrangements?</li><li>How would overnight assistance and daily supports be organised?</li></ul></div></div><p>Disability Forever Homes coordinates inspections and suitability checks. The owner confirms High Physical Support enrolment. Ask for the current enrolment documents and check the completed home against your individual requirements. Enquiries involving other SDA categories are welcome, subject to assessment.</p></section>{plans}{cta()}</div>'''
page('/the-home/','The home & accessibility | SDA Tarneit','Explore the Social Street home’s bedrooms, shower bathrooms, shared spaces and outdoor areas. View the 2D layout and separately labelled 3D concept.',features)

location=f'''<div class="wrap"><section class="page-intro"><p class="eyebrow">TARNEIT · WYNDHAM · MELBOURNE’S WEST</p><h1>A home in a real neighbourhood.</h1><p>Get a feel for the surroundings, then check the places and routes that matter in your day-to-day life.</p></section><section class="location-grid"><article>{img('nearby-playground','Aerial photograph of the local playground and surrounding paths',eager=True)}<div><p class="eyebrow">TIME OUTDOORS</p><h2>Local playground & open space</h2><p>The supplied property imagery shows a playground and surrounding paths, identified in the footage as Gathering Grove Playground / Grove Wetlands. These photographs help introduce the neighbourhood; they do not establish accessibility or the route from the home.</p></div></article><article>{img('nearby-shopping','Aerial photograph of Tarneit Central shopping centre')}<div><p class="eyebrow">EVERYDAY AMENITIES</p><h2>Tarneit Central</h2><p>The supplied photographs also show Tarneit Central shopping centre. Consider the shops and services you use regularly, and check the access, transport and support you would need for those trips.</p></div></article></section><aside class="note">Distances printed on the supplied images have not been independently verified. We have not used them as travel or accessibility promises.</aside><section class="section-space two-columns"><div><h2>Considering SDA in Wyndham?</h2><p>If you are comparing SDA accommodation in Melbourne’s western suburbs, this website gives you a detailed look at one home on Social Street in Tarneit. “Western Melbourne” here means the western suburbs; it does not refer to the suburb of West Melbourne.</p><p>There are no other properties listed on this website. Enquire specifically about the Social Street home so the owner can help you with relevant questions.</p></div><div><h2>Plan the trips that matter to you</h2><ul class="check-list"><li>Choose the shops, activities and services that are important to your routine.</li><li>Check paths, crossings and entrances using your own access requirements.</li><li>Discuss transport and support arrangements with your support team.</li><li>Use an inspection to assess the arrival route and driveway, not just the rooms.</li></ul><p>Station, hospital and travel-time information is not included until it has been checked.</p></div></section>{cta()}</div>'''
page('/living-in-tarneit/','Living in Tarneit, Wyndham | SDA Tarneit','See supplied neighbourhood photos of the local playground and Tarneit Central. Explore the setting of this one SDA home in Melbourne’s western suburbs.',location)

support=f'''<div class="wrap narrow"><section class="page-intro"><p class="eyebrow">SDA, SUPPORT & YOUR QUESTIONS</p><h1>Understand the home.<br>Clarify the support.</h1><p>A practical starting point for participants, families, support coordinators and SIL providers.</p></section><section class="section-space"><h2>SDA and daily supports are different</h2><p>Specialist disability accommodation is housing designed for people with extreme functional impairment or very high support needs. SDA is about the home; it does not include daily support services such as supported independent living (SIL).</p><p>Discuss housing and your day-to-day support arrangements separately. The presence of an overnight onsite assistance room does not establish the hours, staffing or provider of support.</p><p class="source">Read the official NDIS guidance on <a href="{NDIS}">specialist disability accommodation</a> and <a href="{SIL}">supported independent living</a>.</p></section><section class="tinted"><p class="eyebrow">HIGH PHYSICAL SUPPORT</p><h2>Looking for HPS accommodation in Tarneit?</h2><p>High Physical Support is an SDA design category. Before relying on a home’s classification, ask for its current enrolment and design-category information and discuss the actual fittings and equipment with the property manager.</p><p>The owner confirms that this home is enrolled for High Physical Support. Enquiries involving other SDA categories are also welcome. This does not automatically establish eligibility, a funding match or suitability: those checks still need to happen for each person.</p></section><section class="section-space"><h2>Frequently asked questions</h2>{faq('How many participant bedrooms are there?','<p>Two. There is also one separate overnight onsite assistance (OOA) bedroom. The OOA room is not a third participant bedroom.</p>')}{faq('How many bathrooms are there?','<p>The owner has confirmed three shower bathrooms: two participant ensuites and the OOA ensuite. There are no bathtubs. The 3D concept may show different fittings, so use the 2D plan and actual photographs when assessing the layout.</p>')}{faq('Is this home currently available?','<p>Current vacancies, room allocation and move-in dates must be confirmed with the owner. The recorded images may contain older availability captions.</p>')}{faq('Is furniture included?','<p>One participant bedroom is shown furnished, and there are furnishings in the shared spaces. Photographs and the 3D concept do not establish inclusions. Ask what would be included before making arrangements.</p>')}{faq('Who provides SIL or overnight support?','<p>No SIL provider, staffing model or overnight support arrangement is confirmed by this website. The OOA room is a physical space. Discuss support provision separately with your support team and the property manager.</p>')}{faq('Will my NDIS funding cover this home?','<p>This website cannot determine eligibility or the match between your plan and a property. Speak with your support coordinator or the NDIS and ask for current property enrolment information.</p>')}{faq('Who will arrange an inspection?','<p>Send your questions to the owner first. Disability Forever Homes, the property manager, coordinates inspections and suitability checks.</p>')}{faq('Can a family member, support coordinator or SIL provider enquire?','<p>Yes. You can explain your role and ask initial questions. Please do not send NDIS numbers, medical reports or sensitive documents in a first enquiry. If you are acting for someone else, make sure they are comfortable with the information you share.</p>')}{faq('Does this website list other SDA homes in western Melbourne?','<p>No. It showcases one actual SDA home on Social Street in Tarneit, within Wyndham.</p>')}</section>{cta()}</div>'''
page('/sda-and-support/','SDA, High Physical Support & support FAQs | SDA Tarneit','Understand SDA and support arrangements, the OOA bedroom, HPS questions, furniture and inspections at this Tarneit home. Read practical accommodation FAQs.',support)

email=cfg['ownerEmail'].strip();phone=cfg['ownerPhone'].strip()
if email and not re.fullmatch(r'[^\s@<>]+@[^\s@<>]+\.[^\s@<>]+',email):raise ValueError('Invalid ownerEmail')
contact=(f'<a class="contact-detail" href="mailto:{e(email)}">{e(email)}</a>' if email else '')+(f'<a class="contact-detail" href="tel:{e(re.sub(r"[^+0-9]","",phone))}">{e(phone)}</a>' if phone else '')
notice=('Prepare an enquiry to send from your own email app, or use the phone and email above.' if email else 'Owner contact details are being finalised. This form cannot send an enquiry yet.')
enquiries=f'''<div class="wrap"><section class="page-intro"><p class="eyebrow">ENQUIRIES & INSPECTIONS</p><h1>Let’s start with your questions.</h1><p>Ask about the home, discuss what you need to check, or express interest in an inspection.</p></section><div class="enquiry-layout"><section class="enquiry-context"><h2>Talk to the owner</h2><p>Your initial enquiry is for the owner of the Social Street home. Inspections and suitability checks are coordinated through Disability Forever Homes, the property manager.</p>{contact}<ol class="steps"><li><strong>Tell us what you’re exploring</strong><span>A general question, current availability or an inspection.</span></li><li><strong>Clarify the essentials</strong><span>Discuss the home, its current position and your next questions.</span></li><li><strong>Arrange an individual check</strong><span>Inspection and suitability steps are coordinated with the property manager.</span></li></ol><p>No vacancy, inspection time, funding outcome or support arrangement is guaranteed by submitting an enquiry.</p></section><section class="form-panel"><h2>Ask about this home</h2><p id="form-availability" class="note" role="status">{notice}</p><form id="enquiry-form" data-email="{e(email)}" action="/api/enquiries" method="post"><fieldset id="enquiry-fields" disabled><legend class="sr-only">Your enquiry details</legend><div class="field-row"><label>Your name <span>(required)</span><input name="name" autocomplete="name" required maxlength="100"></label><label>Email <span>(required)</span><input type="email" name="email" autocomplete="email" required maxlength="254"></label></div><div class="field-row"><label>Phone <span>(optional)</span><input type="tel" name="phone" autocomplete="tel" maxlength="40"></label><label>I am enquiring as<select name="role"><option>A participant</option><option>A family member</option><option>A support coordinator</option><option>A SIL provider</option><option>Someone else</option></select></label></div><label>I’d like to ask about<select name="topic"><option>The home and suitability</option><option>Current availability</option><option>Arranging an inspection</option><option>Something else</option></select></label><label>Your questions <span>(required)</span><textarea name="message" rows="5" required minlength="10" maxlength="4000" aria-describedby="message-help"></textarea></label><p id="message-help" class="field-help">Please keep this to an initial enquiry. Do not include NDIS numbers, medical records or sensitive documents.</p><div class="honeypot" aria-hidden="true"><label>Leave this blank<input name="website" tabindex="-1" autocomplete="off"></label></div><label class="checkbox"><input type="checkbox" name="consent" required><span>I agree to be contacted about my enquiry and have read the <a href="/privacy/">privacy information</a>.</span></label><button type="submit" class="button">Send enquiry <span aria-hidden="true">↗</span></button></fieldset><noscript><p>Online sending requires JavaScript. Use the owner’s contact details when available.</p></noscript><p id="form-result" role="status" aria-live="polite"></p></form></section></div></div>'''
page('/enquiries/','Accommodation enquiries & inspections | SDA Tarneit','Ask the owner about the Social Street SDA home in Tarneit. Disability Forever Homes coordinates property inspections and individual suitability checks.',enquiries)

privacy='''<div class="wrap narrow"><section class="page-intro"><p class="eyebrow">YOUR INFORMATION</p><h1>Privacy & enquiries</h1><p>Keep your first enquiry simple. Detailed personal information is not needed to ask about the home.</p></section><section class="section-space prose"><h2>What an enquiry asks for</h2><p>The form asks for your name, email, optional phone number, role, enquiry topic and message. Please do not include NDIS participant numbers, medical records, financial documents or other sensitive information.</p><h2>How an enquiry is used</h2><p>When online sending is enabled, your enquiry is sent to the owner’s configured enquiry destination so they can respond about this home. Inspections and suitability checks are coordinated through Disability Forever Homes; discuss any further sharing of personal information before providing it.</p><p>In email-draft mode, the form opens your email app so you can review and send the enquiry yourself. The website does not submit that draft or confirm that it has been sent. A successful sending message means the configured enquiry service accepted the message, not that an inspection or accommodation has been approved.</p><h2>Website operation</h2><p>This version has no advertising trackers, analytics scripts or third-party video embeds. Photos and the walkthrough are served from this website. Ordinary server and Cloudflare network logs may contain technical request information.</p><p>Enquiry content is not stored in browser storage or logged by this website’s application. If sending is enabled, the configured delivery service and recipient’s mailbox will handle the submitted information.</p><h2>Questions or corrections</h2><p>Use the owner’s contact details on the <a href="/enquiries/">enquiries page</a> to ask about information you have submitted, or to request a correction. Email-draft enquiries are handled by your email provider and the owner’s mailbox. Direct website delivery is only enabled when a delivery service has been configured.</p></section></div>'''
page('/privacy/','Privacy & enquiry information | SDA Tarneit','How initial accommodation enquiries and technical website information are handled by SDA Tarneit.',privacy)
walkthrough=f'''<div class="wrap narrow"><section class="page-intro"><p class="eyebrow">EXPLORE THE ACTUAL HOME</p><h1>Walk through Social Street.</h1><p>A recorded walkthrough · 2 min 15 sec. Press play when you’re ready.</p></section><video class="walkthrough-video" controls playsinline preload="none" poster="/assets/photo-051-800.webp" src="/assets/tarneit-720p.mp4" aria-label="Recorded walkthrough of the Social Street home"></video><p class="media-disclaimer">This is recorded property marketing footage. On-screen availability, postcode, distances and design-category captions may be historical; use the corrected written information on this website and ask for current confirmation.</p><section class="section-space"><h2>A text guide to the walkthrough</h2><p>The video starts outside the home and moves through the entrance, the overnight assistance room and its shower ensuite. It then shows the furnished first participant bedroom and ensuite, the shared kitchen, dining and living areas, and the second participant bedroom and ensuite.</p><p>The final section shows the alfresco, rear garden, garage, laundry, air conditioning and alarm panel, followed by nearby playground and shopping-centre imagery. The <a href="/the-home/">home page</a> describes the layout and the <a href="/#all-photos">photo gallery</a> provides labelled stills of these spaces.</p><p>Furniture and equipment pictured do not establish what is included. Ask the owner about the current home before relying on recorded footage.</p></section>{cta()}</div>'''
page('/walkthrough/','Property walkthrough — 2 min 15 sec | SDA Tarneit','Watch the recorded walkthrough of the Social Street home in Tarneit, with a text guide and labelled photo alternatives.',walkthrough)

